svg.script:
function showTooltip(evt){var svg=evt.target.ownerSVGElement;var tip=svg.getElementById('chart-tooltip');var bg=svg.getElementById('chart-tooltip-bg');var body=svg.getElementById('chart-tooltip-body');var raw=evt.currentTarget.getAttribute('data-tip')||'';var color=evt.currentTarget.getAttribute('data-color')||'#111827';var lines=raw.split('||');while(body.firstChild){body.removeChild(body.firstChild);}for(var i=0;i<lines.length;i++){var t=document.createElementNS('http://www.w3.org/2000/svg','tspan');t.setAttribute('x','0');t.setAttribute('dy',i===0?'0':'18');if(i===0){t.setAttribute('font-weight','700');t.setAttribute('fill',color);}t.textContent=lines[i];body.appendChild(t);}tip.setAttribute('visibility','visible');requestAnimationFrame(function(){var box=body.getBBox();var px=12,py=10;bg.setAttribute('width',box.width+px*2);bg.setAttribute('height',box.height+py*2);bg.setAttribute('x',-px);bg.setAttribute('y',-box.height+box.y-py);moveTooltip(evt);});}
function moveTooltip(evt){var svg=evt.target.ownerSVGElement;var tip=svg.getElementById('chart-tooltip');if(tip.getAttribute('visibility')!=='visible') return;var pt=svg.createSVGPoint();pt.x=evt.clientX;pt.y=evt.clientY;var cursor=pt.matrixTransform(svg.getScreenCTM().inverse());var x=cursor.x+16;var y=cursor.y-16;tip.setAttribute('transform','translate('+x+','+y+')');}
function hideTooltip(evt){var svg=evt.target.ownerSVGElement;svg.getElementById('chart-tooltip').setAttribute('visibility','hidden');}
